pub fn testIteratornocontrolNextcodepointPeekcodepoint() !void {
        const str: []const u8 = "👩🏽‍🚀🇨🇭";
        var it = utf8IteratorNoControl(str);
        _ = &it;
        _ = try std.testing.expect((it.i == 0));
