        _ = &result;
        _ = try std.testing.expect((it.i == 0));
        _ = try std.testing.expect((result.?.code_point == 128105));
        _ = try std.testing.expect((result.?.is_break == false));
        result = it.nextCodePoint();
        _ = try std.testing.expect((it.i == 4));
        _ = try std.testing.expect((result.?.code_point == 128105));
        _ = try std.testing.expect((result.?.is_break == false));
        result = it.nextCodePoint();
        _ = try std.testing.expect((result.?.code_point == 127997));
        _ = try std.testing.expect((result.?.is_break == false));
        result = it.nextCodePoint();
        _ = try std.testing.expect((result.?.code_point == 8205));
        _ = try std.testing.expect((result.?.is_break == false));
        result = it.peekCodePoint();
        _ = try std.testing.expect((result.?.code_point == 128640));
        _ = try std.testing.expect((result.?.is_break == true));
        result = it.nextCodePoint();
        _ = try std.testing.expect((it.i == 15));
        _ = try std.testing.expect((result.?.code_point == 128640));
        _ = try std.testing.expect((result.?.is_break == true));
        _ = try std.testing.expect(std.mem.eql(u8, str[0..it.i], "👩🏽‍🚀"));
        result = it.nextCodePoint();
        _ = try std.testing.expect((result.?.code_point == 127464));
        _ = try std.testing.expect((result.?.is_break == false));
        result = it.nextCodePoint();
        _ = try std.testing.expect((it.i == str.len));
        _ = try std.testing.expect((result.?.code_point == 127469));
        _ = try std.testing.expect((result.?.is_break == true));
        _ = try std.testing.expect((it.peekCodePoint() == null));
        _ = try std.testing.expect((it.nextCodePoint() == null));
        _ = try std.testing.expect((it.nextCodePoint() == null));
}

