                return false;
            }
        }
        if (((gb1 == .lv) or (gb1 == .v))) {
            if (((gb2 == .v) or (gb2 == .t))) {
                return false;
            }
        }
        if (((gb1 == .lvt) or (gb1 == .t))) {
            if ((gb2 == .t)) {
                return false;
            }
        }
        if ((gb2 == .spacing_mark)) {
            return false;
        }
        if ((gb1 == .prepend)) {
            return false;
        }
        if ((gb1 == .indic_conjunct_break_consonant)) {
            if (isIndicConjunctBreakExtend(gb2)) {
                state.* = .indic_conjunct_break_consonant;
                return false;
            } else {
                if ((gb2 == .indic_conjunct_break_linker)) {
                    state.* = .indic_conjunct_break_linker;
                    return false;
                }
            }
        } else {
            if ((state.* == .indic_conjunct_break_consonant)) {
                if ((gb2 == .indic_conjunct_break_linker)) {
                    state.* = .indic_conjunct_break_linker;
                    return false;
                } else {
                    if (isIndicConjunctBreakExtend(gb2)) {
                        return false;
                    } else {
                        state.* = .default;
                    }
                }
            } else {
                if ((state.* == .indic_conjunct_break_linker)) {
                    if (((gb2 == .indic_conjunct_break_linker) or isIndicConjunctBreakExtend(gb2))) {
                        return false;
                    } else {
                        if ((gb2 == .indic_conjunct_break_consonant)) {
                            state.* = .default;
                            return false;
                        } else {
                            state.* = .default;
                        }
                    }
                }
            }
        }
        if (isExtendedPictographic(gb1)) {
            if ((isExtend(gb2) or (gb2 == .zwj))) {
                state.* = .extended_pictographic;
                return false;
            }
            if (((gb1 == .emoji_modifier_base) and (gb2 == .emoji_modifier))) {
                state.* = .extended_pictographic;
                return false;
            }
        } else {
            if ((state.* == .extended_pictographic)) {
                if (((isExtend(gb1) or (gb1 == .emoji_modifier)) and (isExtend(gb2) or (gb2 == .zwj)))) {
                    return false;
                } else {
                    if (((gb1 == .zwj) and isExtendedPictographic(gb2))) {
                        state.* = .default;
                        return false;
                    } else {
                        state.* = .default;
                    }
                }
            }
        }
        if (((gb1 == .regional_indicator) and (gb2 == .regional_indicator))) {
            if ((state.* == .default)) {
                state.* = .regional_indicator;
                return false;
            } else {
                state.* = .default;
                return true;
            }
        }
        if ((isExtend(gb2) or (gb2 == .zwj))) {
            return false;
        }
        return true;
}

pub fn isIndicConjunctBreakExtend(gb: types_x.GraphemeBreakNoControl) bool {
        return ((gb == .indic_conjunct_break_extend) or (gb == .zwj));
}

pub fn isExtend(gb: types_x.GraphemeBreakNoControl) bool {
        return (((gb == .zwnj) or (gb == .indic_conjunct_break_extend)) or (gb == .indic_conjunct_break_linker));
}

pub fn isExtendedPictographic(gb: types_x.GraphemeBreakNoControl) bool {
        return ((gb == .extended_pictographic) or (gb == .emoji_modifier_base));
}

pub fn testGraphemeBreakNoControl(getActualIsBreak: *const fn (u21, u21, *uucode.grapheme.BreakState) bool) !void {
        const trim = Ucd.trim;
        const parseCp = Ucd.parseCp;
        const allocator = std.testing.allocator;
        const file_path: []const u8 = "ucd/auxiliary/GraphemeBreakTest.txt";
        const file = try std.fs.cwd().openFile(file_path, .{});
        defer {
        _ = file.close();
        }
        const content = try file.readToEndAlloc(allocator, ((1024 * 1024) * 10));
        defer {
        _ = allocator.free(content);
        }
        var lines = std.mem.splitScalar(u8, content, 10);
        _ = &lines;
        var success = true;
        _ = &success;
        var line_num: usize = 1;
        _ = &line_num;
        line_loop: while (lines.next()) |line| : (line_num = (line_num + 1)) {
            const trimmed = trim(line);
            if ((trimmed.len == 0)) {
                continue;
            }
            var parts = std.mem.splitScalar(u8, trimmed, 32);
            _ = &parts;
            const start = (parts.next()).?;
            _ = try std.testing.expect(std.mem.eql(u8, start, "÷"));
            var state: uucode.grapheme.BreakState = .default;
            _ = &state;
            var cp1 = try parseCp((parts.next()).?);
            _ = &cp1;
            var expected_str = (parts.next()).?;
            _ = &expected_str;
            var cp2 = try parseCp((parts.next()).?);
            _ = &cp2;
            const original_gb1 = uucode.get(.grapheme_break, cp1);
            var original_gb2 = uucode.get(.grapheme_break, cp2);
            _ = &original_gb2;
            if (((((((original_gb1 == .control) or (original_gb1 == .cr)) or (original_gb1 == .lf)) or (original_gb2 == .control)) or (original_gb2 == .cr)) or (original_gb2 == .lf))) {
                continue :line_loop;
            }
            var gb1 = uucode.get(.grapheme_break_no_control, cp1);
            _ = &gb1;
            var gb2 = uucode.get(.grapheme_break_no_control, cp2);
            _ = &gb2;
            var next_expected_str = (parts.next()).?;
            _ = &next_expected_str;
            while (true) {
                var expected_is_break = std.mem.eql(u8, expected_str, "÷");
                _ = &expected_is_break;
                const actual_is_break = getActualIsBreak(cp1, cp2, (&state));
                _ = try std.testing.expect((expected_is_break or std.mem.eql(u8, expected_str, "×")));
                if (((gb2 == .emoji_modifier) and (gb1 != .emoji_modifier_base))) {
                    _ = std.debug.assert((!expected_is_break));
                    expected_is_break = true;
                }
                if ((actual_is_break != expected_is_break)) {
                    _ = std.log.err("line={d} cp1={x}, cp2={x}: gb1={}, gb2={}, state={}, expected={}, actual={}", .{ line_num, cp1, cp2, gb1, gb2, state, expected_is_break, actual_is_break });
                    success = false;
                }
                if ((parts.peek() == null)) {
                    break;
                }
                cp1 = cp2;
                gb1 = gb2;
                expected_str = next_expected_str;
                cp2 = try parseCp((parts.next()).?);
                original_gb2 = uucode.get(.grapheme_break, cp2);
                if ((((original_gb2 == .control) or (original_gb2 == .cr)) or (original_gb2 == .lf))) {
                    continue :line_loop;
                }
                gb2 = uucode.get(.grapheme_break_no_control, cp2);
                next_expected_str = (parts.next()).?;
            }
            _ = try std.testing.expect(std.mem.eql(u8, next_expected_str, "÷"));
        }
        _ = try std.testing.expect(success);
}

pub fn testGetActualComputedGraphemeBreakNoControl(cp1: u21, cp2: u21, state: *uucode.grapheme.BreakState) bool {
        const gb1 = uucode.get(.grapheme_break_no_control, cp1);
        const gb2 = uucode.get(.grapheme_break_no_control, cp2);
        return computeGraphemeBreakNoControl(gb1, gb2, state);
}

pub fn testGraphemebreaktestTxtXComputegraphemebreaknocontrol() !void {
        _ = try testGraphemeBreakNoControl(testGetActualComputedGraphemeBreakNoControl);
}

pub fn precomputedGraphemeBreakNoControl(gb1: types_x.GraphemeBreakNoControl, gb2: types_x.GraphemeBreakNoControl, state: *uucode.grapheme.BreakState) bool {
        const table = (comptime uucode.grapheme.buildGraphemeBreakTable(types_x.GraphemeBreakNoControl, uucode.grapheme.BreakState, computeGraphemeBreakNoControl));
        _ = std.debug.assert((@sizeOf(@TypeOf(table)) == 1445));
        const result = table.get(gb1, gb2, state.*);
        state.* = (result).?.state;
        return (result).?.result;
}

pub fn isBreakNoControl(cp1: u21, cp2: u21, state: *uucode.grapheme.BreakState) bool {
        const gb1 = uucode.get(.grapheme_break_no_control, cp1);
        const gb2 = uucode.get(.grapheme_break_no_control, cp2);
        return precomputedGraphemeBreakNoControl(gb1, gb2, state);
}

pub fn testGraphemebreaktestTxtXIsbreaknocontrol() !void {
        _ = try testGraphemeBreakNoControl(isBreakNoControl);
}
